using System.ComponentModel;
using System.Net;
using System.Text;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? builder.Configuration["AI:ApiKey"]
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable or AI:ApiKey in configuration.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

builder.Services.AddSingleton<Notebook>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var notebook = host.Services.GetRequiredService<Notebook>();
var logger = host.Services.GetRequiredService<ILoggerFactory>().CreateLogger("ResearchAgent");

// Build tool definitions from static methods and the notebook instance
var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync),
    AIFunctionFactory.Create(WebSearchTool.FetchPageAsync),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// Create the agent with tools via Microsoft Agent Framework
var agent = new ChatClientAgent(chatClient, tools);

var systemPrompt = """
    You are a research assistant. When given a topic:
    1. Use the WebSearch tool to find relevant information (try 2-3 different queries).
    2. Use FetchPage to read promising URLs from search results.
    3. Use AddNote to save key findings with source attribution.
    4. Use GetNotes to review what you've collected.
    5. Synthesize your notes into a well-structured summary with sources.
    Be thorough but concise. Always cite your sources.
    """;

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent               ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.Write("> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var history = new List<ChatMessage>
    {
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
    };

    Console.WriteLine($"\n🔍 Researching: {topic}\n");

    var options = new AgentInvokeOptions
    {
        MaximumIterations = 15,
    };

    try
    {
        await foreach (var message in agent.InvokeStreamingAsync(history, options))
        {
            if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
            {
                Console.Write(message.Text);
            }

            logger.LogDebug("Agent step: Role={Role}, ContentLength={Length}",
                message.Role, message.Text?.Length ?? 0);
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\n❌ Error: {ex.Message}");
    }

    Console.WriteLine("\n\n---\n");
}

Console.WriteLine("Goodbye!");

// --- Tool implementations ---

/// <summary>Web search tool that uses DuckDuckGo HTML for zero-API-key search.</summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information on a query. Returns a list of result titles and URLs.")]
    public static async Task<string> SearchAsync(
        [Description("The search query")] string query)
    {
        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await Http.GetStringAsync(url);

            var results = new StringBuilder();
            var count = 0;

            // Parse result links from DuckDuckGo HTML response
            var span = html.AsSpan();
            while (count < 8)
            {
                var marker = "class=\"result__a\"";
                var idx = span.IndexOf(marker.AsSpan());
                if (idx < 0) break;
                span = span[(idx + marker.Length)..];

                // Extract href
                var hrefStart = span.IndexOf("href=\"".AsSpan());
                if (hrefStart < 0) break;
                span = span[(hrefStart + 6)..];
                var hrefEnd = span.IndexOf('"');
                if (hrefEnd < 0) break;
                var href = span[..hrefEnd].ToString();
                span = span[hrefEnd..];

                // Extract title text (between > and </a>)
                var tagClose = span.IndexOf('>');
                if (tagClose < 0) break;
                span = span[(tagClose + 1)..];
                var titleEnd = span.IndexOf("</a>".AsSpan());
                if (titleEnd < 0) break;
                var title = StripHtmlTags(span[..titleEnd].ToString());

                if (!string.IsNullOrWhiteSpace(title) && href.StartsWith("http", StringComparison.Ordinal))
                {
                    count++;
                    results.AppendLine($"{count}. {title}");
                    results.AppendLine($"   URL: {href}");
                }
            }

            return count > 0
                ? results.ToString()
                : "No results found. Try a different query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Fetch and extract text content from a web page URL. Use this to read full articles.")]
    public static async Task<string> FetchPageAsync(
        [Description("The URL to fetch")] string url)
    {
        try
        {
            var html = await Http.GetStringAsync(url);
            var text = StripHtmlTags(html);

            // Collapse whitespace and limit length
            var cleaned = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ").Trim();
            return cleaned.Length > 4000 ? cleaned[..4000] + "... [truncated]" : cleaned;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }

    private static string StripHtmlTags(string html)
    {
        // Remove script/style blocks then tags
        var noScript = System.Text.RegularExpressions.Regex.Replace(html, @"<(script|style)[^>]*>.*?</\1>", "", System.Text.RegularExpressions.RegexOptions.Singleline);
        return System.Text.RegularExpressions.Regex.Replace(noScript, @"<[^>]+>", " ");
    }
}

/// <summary>Note-taking tool that stores research findings in memory.</summary>
class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Save a research note. Include the source URL and a concise finding.")]
    public string AddNote(
        [Description("The note content including source attribution")] string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieve all saved research notes to review before writing a summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
            sb.AppendLine($"[{i + 1}] {_notes[i]}");
        return sb.ToString();
    }

    public void Clear() => _notes.Clear();
}

