var chatClient = host.Services.GetRequiredService<IChatClient>();
var notebook = host.Services.GetRequiredService<Notebook>();
var loggerFactory = host.Services.GetRequiredService<ILoggerFactory>();
var logger = loggerFactory.CreateLogger("ResearchAgent");

// Build tool definitions from static methods and the notebook instance
var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync),
    AIFunctionFactory.Create(WebSearchTool.FetchPageAsync),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

var systemPrompt = """
    You are a research assistant. When given a topic:
    1. Use the SearchAsync tool to find relevant information (try 2-3 different queries).
    2. Use FetchPageAsync to read promising URLs from search results.
    3. Use AddNote to save key findings with source attribution.
    4. Use GetNotes to review what you've collected.
    5. Synthesize your notes into a well-structured summary with sources.
    Be thorough but concise. Always cite your sources.
    """;

// Create the agent with tools via Microsoft Agent Framework
var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI agent that researches topics using web search and note-taking.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 4096,
            Tools = [.. tools],
        },
    },
    loggerFactory);

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent              ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.Write("> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();
    Console.WriteLine($"\n🔍 Researching: {topic}\n");

    try
    {
        var session = await agent.CreateSessionAsync(
            Guid.NewGuid().ToString(), CancellationToken.None);

        var userMessage = $"Research the following topic and provide a comprehensive summary: {topic}";
        var runOptions = new ChatClientAgentRunOptions(new ChatOptions
        {
            Instructions = systemPrompt,
            Temperature = 0f,
            MaxOutputTokens = 4096,
            Tools = [.. tools],
        });

        await foreach (var update in agent.RunStreamingAsync(
            userMessage, session, runOptions, CancellationToken.None))
        {
            if (!string.IsNullOrEmpty(update.Text))
            {
                Console.Write(update.Text);
            }

            logger.LogDebug("Agent step: Role={Role}, ContentLength={Length}",
                update.Role, update.Text?.Length ?? 0);
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\n❌ Error: {ex.Message}");
        logger.LogError(ex, "Agent execution failed");
    }

    Console.WriteLine("\n\n---\n");
}

Console.WriteLine("Goodbye!");

