145. 
146.             var results = new StringBuilder();
147.             var count = 0;
148. 
149.             // Parse result links from DuckDuckGo HTML response
150.             var span = html.AsSpan();
151.             while (count < 8)
152.             {
153.                 var marker = "class=\"result__a\"";
154.                 var idx = span.IndexOf(marker.AsSpan());
155.                 if (idx < 0) break;
156.                 span = span[(idx + marker.Length)..];
157. 
158.                 // Extract href
159.                 var hrefStart = span.IndexOf("href=\"".AsSpan());
160.                 if (hrefStart < 0) break;
