171.                 var titleEnd = span.IndexOf("</a>".AsSpan());
172.                 if (titleEnd < 0) break;
173.                 var title = StripHtmlTags(span[..titleEnd].ToString());
174. 
175.                 if (!string.IsNullOrWhiteSpace(title) && href.StartsWith("http", StringComparison.Ordinal))
176.                 {
177.                     count++;
178.                     results.AppendLine($"{count}. {title}");
179.                     results.AppendLine($"   URL: {href}");
180.                 }
181.             }
182. 
183.             return count > 0
184.                 ? results.ToString()
185.                 : "No results found. Try a different query.";
186.         }
187.         catch (Exception ex)
188.         {
189.             return $"Search failed: {ex.Message}";
190.         }
191.     }
